style.css:
/* Aero Paradise — Roblox Homepage */

:root {
  /* swap these colours if you want */
  --my-aero-blue: #38bafa;
  --my-aero-green: #66d94b;
}

/* Frutiger Aero background */
html,
body {
  min-height: 100% !important;
  background-color: var(--my-aero-blue) !important;
  background-image:
    url("https://i.postimg.cc/zDYddDy2/Frutiger-ero-background.jpg") !important;
  background-position: center center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

/* Roblox homepage content */
body {
  font-family: "Trebuchet MS", Arial, sans-serif !important;
}

/* glossy links */
a {
  transition: color 0.2s ease !important;
}

/* smooth Aero appearance */
img {
  border-radius: 10px;
}
